// Live hair: HAIR COLOUR only. It recolours your REAL hair using a hair-segmentation mask (the model marks which pixels are hair),
// keeping the texture, light and shadow of your own hair. Hairstyles (cuts) are not shown live: a flat shape over a live camera
// can never look like real hair, so hairstyles are generated by AI from a photo in the "AI Photo" tab instead.
const sh = (n, c) => ({ n, c })
const HAIR_SHADES = [sh('Black', '#14110F'), sh('Dark brown', '#3B2418'), sh('Chestnut', '#6B3E26'), sh('Auburn', '#8B3A1F'), sh('Honey blonde', '#C9A25B'), sh('Platinum', '#E6DCC3'), sh('Burgundy', '#5A0F2A'), sh('Copper', '#B5582B'), sh('Ash grey', '#9AA0A6'), sh('Rose pink', '#D9708F'), sh('Midnight blue', '#1C2B5A')]
export const HAIR = [{ id: 'haircolor', label: 'Hair colour', v: 0.8, shades: HAIR_SHADES, excl: 'haircolor', need: 'face+seg' }] // the face tracker keeps colour off the face and moves the mask with the head
const rgb = (hx) => [1, 3, 5].map((i) => parseInt(hx.slice(i, i + 2), 16))
export const FACE_OVAL = [10, 338, 297, 332, 284, 251, 389, 356, 454, 323, 361, 288, 397, 365, 379, 378, 400, 377, 152, 148, 176, 149, 150, 136, 172, 58, 132, 93, 234, 127, 162, 21, 54, 103, 67, 109]

// ---- hair colour (segmentation) ----
// The hair mask comes from render/masks.js (segmenter labels refined against the camera picture with a guided filter, then
// smoothed over time less when the head moves fast). The colour is applied with the lighting-aware tint, which keeps the real
// strands, shine and shadows.
import { tintRegion, meanLum } from './render/tint.js'
let lumT = 0, lum = null
export function drawHairColour(c, mask, tint, state, w, h, raw, off = null) { // off: shift of the mask to the current frame
  const st = state.haircolor; if (!st || !mask.width) return
  const col = HAIR.find((p) => p.id === 'haircolor').shades[st.shade].c
  const now = performance.now(); if (raw && now - lumT > 400) { lumT = now; const m = meanLum(raw, mask); if (m != null) lum = lum == null ? m : lum * 0.7 + m * 0.3 }
  tintRegion(c, mask, col, st.v, lum, w, h, { minScale: 0.3, lighten: 0.75, richness: 0.25, dx: off?.x || 0, dy: off?.y || 0 })
}

// ---- hair colour, current pipeline (Update 13) ----
// 1. the hair mask (render/masks.js: Hair Segmenter -> guided filter against the picture -> motion-compensated smoothing)
// 2. moved to THIS frame with the head's own movement since the mask was made (position, size AND rotation, from the eye corners),
//    so colour stays on the hair when the head turns or tilts between two segmenter runs
// 3. protected areas removed: eyes, eyebrows and lips never get hair colour (segmenters often call brows and lashes "hair"),
//    and inside the face outline the mask must be more certain (a fringe yes, forehead skin no)
// 4. recoloured per pixel on the GPU (render/haircolor.js): texture, shine and shadows of the real hair kept
// Falls back to the 2D tint above when WebGL is not available.
import { createHairColour } from './render/haircolor.js'
import { lumOf } from './render/tint.js'
const PROTECT = [
  [33, 246, 161, 160, 159, 158, 157, 173, 133, 155, 154, 153, 145, 144, 163, 7], [263, 466, 388, 387, 386, 385, 384, 398, 362, 382, 381, 380, 374, 373, 390, 249],
  [46, 53, 52, 65, 55, 107, 66, 105, 63, 70], [276, 283, 282, 295, 285, 336, 296, 334, 293, 300],
  [61, 185, 40, 39, 37, 0, 267, 269, 270, 409, 291, 375, 321, 405, 314, 17, 84, 181, 91, 146],
]
export function createHairRenderer() {
  const hm = document.createElement('canvas'), fm = document.createElement('canvas')
  let gpu, lumT2 = 0, lum2 = null
  // c: target; mask: hair mask canvas (any size, framing of the picture); raw: shown picture; M: tracked face or null;
  // T: 2D transform { a, b, c, d, e, f } (picture pixels) from the mask's frame to this frame, or null
  function draw(c, mask, state, w, h, raw, M, T) {
    const st = state.haircolor; if (!st || !mask?.width) return
    const col = HAIR.find((p) => p.id === 'haircolor').shades[st.shade].c
    if (hm.width !== mask.width || hm.height !== mask.height) { hm.width = fm.width = mask.width; hm.height = fm.height = mask.height }
    const kx = mask.width / w, ky = mask.height / h, hx = hm.getContext('2d'), fx = fm.getContext('2d')
    hx.setTransform(1, 0, 0, 1, 0, 0); hx.clearRect(0, 0, hm.width, hm.height); hx.imageSmoothingEnabled = true
    hx.setTransform(kx, 0, 0, ky, 0, 0); if (T) hx.transform(T.a, T.b, T.c, T.d, T.e, T.f); hx.drawImage(mask, 0, 0, w, h)
    fx.setTransform(1, 0, 0, 1, 0, 0); fx.clearRect(0, 0, fm.width, fm.height)
    if (M) {
      const poly = (x, ids) => { x.beginPath(); ids.forEach((i, k) => (k ? x.lineTo(M.P[i].x, M.P[i].y) : x.moveTo(M.P[i].x, M.P[i].y))); x.closePath() }
      hx.setTransform(kx, 0, 0, ky, 0, 0); hx.globalCompositeOperation = 'destination-out'; hx.fillStyle = hx.strokeStyle = '#000'; hx.lineJoin = 'round'; hx.lineWidth = M.fw * 0.035
      PROTECT.forEach((ids) => { poly(hx, ids); hx.fill(); hx.stroke() }); hx.globalCompositeOperation = 'source-over'
      fx.setTransform(kx, 0, 0, ky, 0, 0); fx.fillStyle = '#000'; fx.shadowColor = '#000'; fx.shadowBlur = M.fw * 0.05 * kx; poly(fx, FACE_OVAL); fx.fill()
    }
    hx.setTransform(1, 0, 0, 1, 0, 0); fx.setTransform(1, 0, 0, 1, 0, 0)
    const now = performance.now(); if (raw && now - lumT2 > 400) { lumT2 = now; const m = meanLum(raw, hm); if (m != null) lum2 = lum2 == null ? m : lum2 * 0.7 + m * 0.3 }
    if (gpu === undefined) { try { gpu = createHairColour() } catch { gpu = null } }
    if (gpu && gpu.ok) {
      const rgb01 = rgb(col).map((v) => v / 255), out = gpu.render(raw, hm, fm, rgb01, lum2 ?? 0.25, lumOf(col), st.v)
      if (out) { c.drawImage(out, 0, 0); return 'gpu' }
    }
    tintRegion(c, hm, col, st.v, lum2, w, h, { minScale: 0.3, lighten: 0.75, richness: 0.25 })
    return '2d'
  }
  return { draw, reset() { lum2 = null; lumT2 = 0 }, dispose() { gpu?.dispose(); gpu = undefined } }
}
